"use client"

import * as React from "react"
import { Select as SelectPrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { selectContentRecipe, selectTriggerRecipe } from "@/lib/ink/recipes/select-ink"
import { cn } from "@/lib/utils"

const SelectDisabledContext = React.createContext(false)

function Select(props: React.ComponentProps<typeof SelectPrimitive.Root>) {
  return (
    <SelectDisabledContext.Provider value={!!props.disabled}>
      <SelectPrimitive.Root data-slot="select" {...props} />
    </SelectDisabledContext.Provider>
  )
}

function SelectGroup(props: React.ComponentProps<typeof SelectPrimitive.Group>) {
  return <SelectPrimitive.Group data-slot="select-group" className={cn("scroll-my-1", props.className)} {...props} />
}

function SelectValue(props: React.ComponentProps<typeof SelectPrimitive.Value>) {
  return <SelectPrimitive.Value data-slot="select-value" {...props} />
}

function SelectTrigger({
  className,
  size = "default",
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Trigger> & {
  size?: "sm" | "default"
  seed?: string | number
}) {
  const invalid = props["aria-invalid"] === true || props["aria-invalid"] === "true"
  const disabled = React.useContext(SelectDisabledContext) || !!props.disabled
  const { hostRef, hostProps, node } = useInk({
    recipe: selectTriggerRecipe,
    params: { disabled, invalid },
    kind: "field",
    seed,
    still: true,
  })

  return (
    <SelectPrimitive.Trigger
      data-slot="select-trigger"
      data-size={size}
      ref={useMergedRef<HTMLButtonElement>(hostRef, ref)}
      {...hostProps}
      className={cn(
        "relative isolate flex h-9 w-full min-w-[8rem] items-center justify-between gap-2 rounded-[var(--radius-md)] ps-3 pe-2 text-start text-sm whitespace-nowrap",
        "text-foreground disabled:cursor-not-allowed disabled:opacity-70 data-[placeholder]:text-muted-foreground",
        "focus-visible:outline-none data-[size=sm]:h-8",
        "*:data-[slot=select-value]:line-clamp-1 *:data-[slot=select-value]:flex *:data-[slot=select-value]:min-w-0 *:data-[slot=select-value]:flex-1",
        className,
      )}
      {...props}
    >
      {node}
      {children}
      <SelectPrimitive.Icon data-slot="select-icon" className="shrink-0 opacity-60" aria-hidden>
        ▾
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  )
}

function SelectContent({
  className,
  children,
  position = "popper",
  seed,
  ...props
}: React.ComponentProps<typeof SelectPrimitive.Content> & { seed?: string | number }) {
  const { hostRef, hostProps, node } = useInk({
    recipe: selectContentRecipe,
    params: {},
    kind: "select-panel",
    seed,
    still: true,
  })

  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        data-slot="select-content"
        position={position}
        className={cn(
          "z-50 max-h-72 min-w-[var(--radix-select-trigger-width)] overflow-hidden text-popover-foreground",
          "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
          className,
        )}
        {...props}
      >
        <div
          ref={hostRef}
          {...hostProps}
          className="relative isolate overflow-hidden rounded-[var(--radius-md)] p-1"
        >
          {node}
          <SelectPrimitive.Viewport className="relative z-[1]">{children}</SelectPrimitive.Viewport>
        </div>
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  )
}

function SelectLabel({ className, ...props }: React.ComponentProps<typeof SelectPrimitive.Label>) {
  return (
    <SelectPrimitive.Label
      data-slot="select-label"
      className={cn("px-2 py-1.5 text-xs font-medium text-muted-foreground", className)}
      {...props}
    />
  )
}

function SelectItem({ className, children, ...props }: React.ComponentProps<typeof SelectPrimitive.Item>) {
  return (
    <SelectPrimitive.Item
      data-slot="select-item"
      className={cn(
        "relative flex w-full cursor-default select-none items-center rounded-sm py-1.5 ps-2 pe-8 text-sm outline-none",
        "focus:bg-[color-mix(in_srgb,var(--sd-rose-wash)_45%,transparent)] focus:text-foreground",
        "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
      <SelectPrimitive.ItemIndicator className="absolute end-2 inline-flex items-center justify-center" aria-hidden>
        ✓
      </SelectPrimitive.ItemIndicator>
    </SelectPrimitive.Item>
  )
}

function SelectSeparator({ className, ...props }: React.ComponentProps<typeof SelectPrimitive.Separator>) {
  return (
    <SelectPrimitive.Separator
      data-slot="select-separator"
      className={cn("-mx-1 my-1 h-px bg-[var(--sd-line-soft)]", className)}
      {...props}
    />
  )
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
}

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import { drawFieldWashFrame, type FieldFrameParams } from '@/lib/ink/recipes/field-wash-frame'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type SelectTriggerParams = FieldFrameParams

export const selectTriggerRecipe = defineRecipe<SelectTriggerParams>({
  id: 'select',
  kind: 'field',
  layers: ['rest', 'hover', 'focus', 'disabled', 'invalid', 'open'],
  lazy: ['focus'],
  pad: 8,
  draw(ink, { w, h }, params, ctx) {
    drawFieldWashFrame(ink, w, h, params, ctx, { radiusFactor: 0.14 })
    if (params.disabled || ctx.lazyOnly) return
    const r = clamp(Math.min(w, h) * 0.14, 3.5, 7)
    const inset = 0.55
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)
    ink.layer('open', () => {
      wash(ink, body, 'horizon', { alpha: 0.18, wobble: 0.7, material: 'wash' })
      box(ink, 0.7, 0.7, w - 1.4, h - 1.4, {
        pen: 'horizonPencil.fine',
        corner: r,
        loose: 0.75,
        opts: { alpha: 0.45, simple: true },
      })
    })
  },
})

export const selectContentRecipe = defineRecipe<Record<string, never>>({
  id: 'select-content',
  kind: 'select-panel',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }) {
    const r = clamp(Math.min(w, h) * 0.035, 4, 9)
    const inset = 0.5
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)
    ink.layer('rest', () => {
      softFill(ink, body, [
        { color: 'sand-slip', alpha: 0.92, wobble: 0.48 },
        { color: 'wash-sky', alpha: 0.12, inset: 1.5, wobble: 0.9 },
      ])
      box(ink, 0.5, 0.5, w - 1, h - 1, {
        pen: 'pencil.fine',
        corner: r,
        loose: 1.1,
        opts: { alpha: 0.5, simple: w > 280 },
      })
    })
  },
})

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { box, focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import type { RecipeContext } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export interface FieldFrameParams {
  disabled?: boolean
  invalid?: boolean
  readOnly?: boolean
}

export interface FieldFrameOptions {
  /** Smaller = rounder corners on tall boxes (textarea). Default 0.14 */
  radiusFactor?: number
}

export function drawFieldWashFrame(
  ink: Ink,
  w: number,
  h: number,
  { disabled, invalid, readOnly }: FieldFrameParams,
  ctx: RecipeContext,
  opt: FieldFrameOptions = {},
) {
  const rf = opt.radiusFactor ?? 0.14
  const r = clamp(Math.min(w, h) * rf, 3.5, 10)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  if (disabled) {
    if (ctx.lazyOnly) return
    ink.layer('disabled', () => {
      wash(ink, body, 'sand-shade', { alpha: 0.48, wobble: 0.45, material: 'wash' })
      box(ink, 0.5, 0.5, w - 1, h - 1, {
        pen: 'pencil.fine',
        corner: r,
        loose: 0.35,
        opts: { alpha: 0.35, simple: true },
      })
    })
    return
  }

  if (invalid) {
    ink.layer('invalid', () => {
      softFill(ink, body, [
        { color: 'wash-rose', alpha: 0.35, wobble: 0.8 },
        { color: 'ember', alpha: 0.18, inset: 0.6 },
      ])
      box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
        pen: 'rose.fine',
        corner: r,
        loose: 1,
        opts: { alpha: 0.75, wobble: 0.4, simple: true, color: 'danger' },
      })
    })
  }

  ctx.lazy('focus', (fink) => {
    wash(fink, body, 'star', { alpha: 0.22, wobble: 0.6, material: 'wash', inset: 0.15 })
    wash(fink, body, 'horizon', { alpha: 0.12, wobble: 0.75, material: 'wash', inset: 1.2 })
    focusRing(fink, 0, 0, w, h, {
      r,
      pen: 'horizonPencil.fine',
      opts: { alpha: 0.9, wobble: 0.32, simple: w < 120 },
    })
  })
  if (ctx.lazyOnly) return

  ink.layer('rest', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.72, wobble: 0.55 },
      { color: 'sand', alpha: 0.28, inset: 0.8 },
    ])
    box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
      pen: readOnly ? 'pencil.fine' : 'rose.fine',
      corner: r,
      loose: readOnly ? 0.5 : 0.95,
      opts: {
        alpha: readOnly ? 0.42 : 0.58,
        wobble: 0.36,
        simple: w < 120,
        color: readOnly ? 'pencil' : 'ink-soft',
      },
    })
  })

  ink.layer('hover', () => {
    if (readOnly) return
    wash(ink, body, 'rose-wash', { alpha: 0.28, wobble: 0.85, material: 'wash' })
    box(ink, 0.8, 0.8, w - 1.6, h - 1.6, {
      pen: 'ink.fine',
      corner: r,
      loose: 0.85,
      opts: { alpha: 0.4, simple: true, color: 'horizon' },
    })
  })
}

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
